// Combine prospect data + reply context (depuis trigger inputs)
const prospect = $json;
const inputs = $('Trigger Sub-workflow').first() ? $('Trigger Sub-workflow').first().json : {};
return [{
  json: {
    ...prospect,
    reply_text_input: inputs.reply_text || prospect.reply_text || '',
    reply_category_input: inputs.reply_category || prospect.reply_category || ''
  }
}];

const out = [];
for (const item of items) {
  const llm = item.json;
  let parsed = {};
  try {
    const c = llm && llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
    if (!c) throw new Error('NO_CONTENT');
    parsed = JSON.parse(c);
  } catch (e) {
    parsed = { _llm_error: String(e && e.message || e) };
  }
  const prospect = $('Build context').first().json;
  const now = new Date().toISOString();
  out.push({
    json: {
      id: 'proj_' + Date.now(),
      prospect_id: prospect.id,
      created_at: now,
      updated_at: now,
      status: parsed._llm_error ? 'error' : 'new',
      client_name: prospect.company_name,
      niche: prospect.niche,
      city: prospect.city,
      email: prospect.email,
      client_brief_summary: parsed.client_brief_summary || '',
      recommended_website_prompt: parsed.recommended_website_prompt || '',
      estimated_project_scope: JSON.stringify(parsed.estimated_project_scope || {}),
      estimated_project_complexity: parsed.estimated_project_complexity || '',
      next_questions_to_ask: JSON.stringify(parsed.next_questions_to_ask || []),
      assigned_to: parsed.suggested_owner || 'Arsène',
      estimated_hours: '',
      priority: 'medium',
      notes: parsed.suggested_owner_reason || ''
    }
  });
}
return out;
